(function(){
  const scenario=window.UxdScenario?window.UxdScenario.get():'default';
  let assets=[{name:'Whisper transcription',url:'https://whisper.apps.cluster.example.com/v1',type:'Custom endpoint',asr:true,status:'Ready',updated:'Oct 16, 2026'},{name:'Granite 3.3 8B',url:'https://granite.apps.cluster.example.com/v1',type:'InferenceService',asr:false,status:'Ready',updated:'Oct 14, 2026'},{name:'Claude Sonnet',url:'https://api.anthropic.com/v1',type:'Custom endpoint',asr:false,status:'Ready',updated:'Oct 10, 2026'}];
  if(scenario==='no-asr')assets=assets.filter(a=>!a.asr);if(scenario==='empty')assets=[];
  const table=document.getElementById('asset-table'),notice=document.getElementById('asset-notice');
  function render(){const q=document.getElementById('asset-search').value.toLowerCase();const rows=assets.filter(a=>(a.name+a.url+a.type).toLowerCase().includes(q));document.getElementById('asset-count').textContent=assets.length+' endpoints';document.getElementById('footer-count').textContent=assets.length?`1-${rows.length} of ${assets.length} endpoints`:'';
    if(scenario==='load-error'){table.innerHTML='<div class="table-empty"><div class="empty-icon error-icon">!</div><h2>Unable to load endpoints</h2><p>There was a problem retrieving AI Asset endpoints.</p><button class="pf-v6-c-button pf-m-secondary" id="retry-assets">Retry</button></div>';document.getElementById('retry-assets').onclick=()=>{notice.textContent='Connection restored. Endpoints loaded.';notice.hidden=false;};return;}
    if(!rows.length){table.innerHTML='<div class="table-empty"><div class="empty-icon">◈</div><h2>'+(assets.length?'No matching endpoints':'No endpoints yet')+'</h2><p>'+(assets.length?'Try a different search.':'Add an AI Asset endpoint to make a model available in Playground.')+'</p>'+(assets.length?'':'<button class="pf-v6-c-button pf-m-primary" id="empty-add">＋ Add endpoint</button>')+'</div>';const b=document.getElementById('empty-add');if(b)b.onclick=openDialog;return;}
    table.innerHTML='<table class="pf-v6-c-table asset-table"><thead><tr><th>Endpoint name</th><th>Type</th><th>Audio transcription</th><th>Status</th><th>Last updated</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>'+rows.map((a,i)=>'<tr><td><strong>'+a.name+'</strong><small class="url-text">'+a.url+'</small></td><td>'+a.type+'</td><td>'+(a.asr?'<span class="pf-v6-c-label pf-m-blue"><span class="pf-v6-c-label__content">Transcription model</span></span>':'<span class="muted">Not enabled</span>')+'</td><td><span class="status-dot"></span>'+a.status+'</td><td>'+a.updated+'</td><td><button class="row-menu" data-index="'+i+'" aria-label="Actions for '+a.name+'">•••</button></td></tr>').join('')+'</tbody></table>';table.querySelectorAll('.row-menu').forEach(b=>b.onclick=()=>{const a=rows[Number(b.dataset.index)];a.asr=!a.asr;render();});}
  function openDialog(){document.getElementById('asset-dialog').showModal();}
  document.getElementById('add-endpoint').onclick=openDialog;document.getElementById('asset-search').addEventListener('input',render);document.getElementById('filter-assets').onclick=()=>{notice.textContent='Showing endpoints in your workspace.';notice.hidden=false;};
  document.getElementById('save-asset').addEventListener('click',e=>{e.preventDefault();const name=document.getElementById('asset-name').value.trim(),url=document.getElementById('asset-url').value.trim();if(!name||!url)return;assets.unshift({name,url,type:'Custom endpoint',asr:document.getElementById('asset-asr').checked,status:'Ready',updated:'Just now'});document.getElementById('asset-dialog').close();notice.textContent=assets[0].asr?'Endpoint added and marked for audio transcription. It is now available in the Playground audio model selector.':'Endpoint added.';notice.hidden=false;render();});
  render();
})();
